/**
 * Memory Stream Store
 *
 * In-memory stream store for local development and testing.
 * Does not persist across restarts.
 */

import type { StreamChunk, StreamEntry } from '../types';
import type { StreamStore, StreamMeta } from './types';

/**
 * In-memory stream store implementation
 */
export class MemoryStreamStore implements StreamStore {
  private streams: Map<string, StreamEntry[]> = new Map();
  private metadata: Map<string, StreamMeta> = new Map();
  private counter: number = 0;

  /**
   * Generate a unique entry ID (similar to Redis format)
   */
  private generateId(): string {
    const timestamp = Date.now();
    const sequence = this.counter++;
    return `${timestamp}-${sequence}`;
  }

  /**
   * Append a chunk to the stream
   */
  async append(streamId: string, chunk: StreamChunk): Promise<string> {
    const id = this.generateId();

    if (!this.streams.has(streamId)) {
      this.streams.set(streamId, []);
    }

    const entries = this.streams.get(streamId)!;
    entries.push({ id, data: chunk });

    return id;
  }

  /**
   * Read chunks from the stream
   */
  async read(streamId: string, fromId: string = '0', count: number = 100): Promise<StreamEntry[]> {
    const entries = this.streams.get(streamId);

    if (!entries || entries.length === 0) {
      return [];
    }

    // Find the starting index
    let startIndex = 0;
    if (fromId !== '0') {
      const foundIndex = entries.findIndex(e => e.id === fromId);
      if (foundIndex !== -1) {
        startIndex = foundIndex + 1; // Start after the found ID
      }
    }

    // Return entries after startIndex, up to count
    return entries.slice(startIndex, startIndex + count);
  }

  /**
   * Get stream metadata
   */
  async getMeta(streamId: string): Promise<StreamMeta | null> {
    return this.metadata.get(streamId) || null;
  }

  /**
   * Set stream metadata
   */
  async setMeta(streamId: string, meta: StreamMeta): Promise<void> {
    this.metadata.set(streamId, meta);
  }

  /**
   * Delete a stream and its metadata
   */
  async delete(streamId: string): Promise<void> {
    this.streams.delete(streamId);
    this.metadata.delete(streamId);
  }

  /**
   * Check if a stream exists
   */
  async exists(streamId: string): Promise<boolean> {
    return this.streams.has(streamId);
  }

  /**
   * Close the connection (no-op for memory store)
   */
  async close(): Promise<void> {
    // No-op - memory store doesn't need cleanup
  }

  /**
   * Clear all streams (useful for testing)
   */
  clear(): void {
    this.streams.clear();
    this.metadata.clear();
    this.counter = 0;
  }

  /**
   * Get the number of streams
   */
  get size(): number {
    return this.streams.size;
  }
}

/**
 * Create a memory stream store instance
 */
export function createMemoryStreamStore(): StreamStore {
  return new MemoryStreamStore();
}


