/**
 * Redis Stream Store
 *
 * Uses Redis Streams for reliable, ordered token streaming.
 * Extracted from Stratus redis-store.ts.
 */

import Redis from 'ioredis';
import type { StreamChunk, StreamEntry } from '../types';
import type { StreamStore, StreamMeta, StreamStoreConfig } from './types';

/**
 * Redis-backed stream store implementation
 */
export class RedisStreamStore implements StreamStore {
  private client: Redis;
  private keyPrefix: string;
  private defaultTtl: number;

  constructor(config: StreamStoreConfig) {
    if (!config.redisUrl) {
      throw new Error('Redis URL is required for RedisStreamStore');
    }

    this.client = new Redis(config.redisUrl, {
      maxRetriesPerRequest: 3,
      lazyConnect: true,
    });

    this.keyPrefix = config.keyPrefix || 'sage:stream:';
    this.defaultTtl = config.defaultTtl || 3600; // 1 hour default

    // Handle connection errors
    this.client.on('error', (err) => {
      console.error('[RedisStreamStore] Connection error:', err);
    });
  }

  /**
   * Get the stream key for a given stream ID
   */
  private streamKey(streamId: string): string {
    return `${this.keyPrefix}${streamId}`;
  }

  /**
   * Get the metadata key for a given stream ID
   */
  private metaKey(streamId: string): string {
    return `${this.keyPrefix}${streamId}:meta`;
  }

  /**
   * Append a chunk to the stream
   */
  async append(streamId: string, chunk: StreamChunk): Promise<string> {
    const key = this.streamKey(streamId);

    // Build fields array
    const fields: string[] = [
      'type', chunk.type,
      'content', chunk.content,
      'timestamp', chunk.timestamp.toString(),
    ];

    if (chunk.toolCallId) {
      fields.push('toolCallId', chunk.toolCallId);
    }
    if (chunk.toolName) {
      fields.push('toolName', chunk.toolName);
    }
    if (chunk.toolArguments) {
      fields.push('toolArguments', chunk.toolArguments);
    }
    if (chunk.status) {
      fields.push('status', chunk.status);
    }

    // Use XADD with auto-generated ID
    const id = await this.client.xadd(key, '*', ...fields);

    if (!id) {
      throw new Error('Failed to append to stream');
    }

    // Set TTL on first write
    const ttl = await this.client.ttl(key);
    if (ttl === -1) {
      await this.client.expire(key, this.defaultTtl);
    }

    return id;
  }

  /**
   * Read chunks from the stream
   */
  async read(streamId: string, fromId: string = '0', count: number = 100): Promise<StreamEntry[]> {
    const key = this.streamKey(streamId);

    // XRANGE from after the given ID
    const results = await this.client.xrange(
      key,
      fromId === '0' ? '-' : `(${fromId}`,
      '+',
      'COUNT',
      count.toString()
    );

    if (!results || results.length === 0) {
      return [];
    }

    return results.map(([id, fields]: [string, string[]]) => {
      // Convert flat array to object
      const data: Record<string, string> = {};
      for (let i = 0; i < fields.length; i += 2) {
        data[fields[i]] = fields[i + 1];
      }

      return {
        id,
        data: {
          type: data.type as StreamChunk['type'],
          content: data.content,
          timestamp: parseInt(data.timestamp, 10),
          toolCallId: data.toolCallId,
          toolName: data.toolName,
          toolArguments: data.toolArguments,
          status: data.status as StreamChunk['status'],
        },
      };
    });
  }

  /**
   * Get stream metadata
   */
  async getMeta(streamId: string): Promise<StreamMeta | null> {
    const key = this.metaKey(streamId);
    const data = await this.client.get(key);

    if (!data) {
      return null;
    }

    try {
      return JSON.parse(data) as StreamMeta;
    } catch {
      return null;
    }
  }

  /**
   * Set stream metadata
   */
  async setMeta(streamId: string, meta: StreamMeta): Promise<void> {
    const key = this.metaKey(streamId);
    await this.client.setex(key, this.defaultTtl, JSON.stringify(meta));
  }

  /**
   * Delete a stream and its metadata
   */
  async delete(streamId: string): Promise<void> {
    const streamKey = this.streamKey(streamId);
    const metaKey = this.metaKey(streamId);

    await this.client.del(streamKey, metaKey);
  }

  /**
   * Check if a stream exists
   */
  async exists(streamId: string): Promise<boolean> {
    const key = this.streamKey(streamId);
    const exists = await this.client.exists(key);
    return exists === 1;
  }

  /**
   * Close the connection
   */
  async close(): Promise<void> {
    await this.client.quit();
  }
}

/**
 * Create a Redis stream store instance
 */
export function createRedisStreamStore(
  redisUrl: string,
  options?: Partial<StreamStoreConfig>
): StreamStore {
  return new RedisStreamStore({
    provider: 'redis',
    redisUrl,
    ...options,
  });
}
